
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbe_sol_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbe_sol", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.243475597135143e+00, -4.160803661164329e+00, -4.045024931589803e+00, -3.884779636788072e+00, -3.666718374169774e+00, -3.377130926788183e+00, -3.005798112734063e+00, -2.552996625223992e+00, -2.039112860014876e+00, -1.509803414011537e+00, -1.016944907177130e+00, -6.940267345301923e-01, -5.966238137203942e-01, -4.890867047154571e-01, -3.524988529151353e-01, -2.248376681526367e-01, -1.251415901547981e-01, -4.886649998620543e-02, -1.080452309883557e-02, -1.216191333161364e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


